import contextlib
import io
import json
import os
import sys


def emit(obj):
    # Write the single final JSON object to the real stdout.
    sys.stdout.write(json.dumps(obj))
    sys.stdout.write("\n")
    sys.stdout.flush()


def load_candidate(path):
    # Read the verbatim candidate source and execute it in an isolated namespace.
    with open(path, "r", encoding="utf-8") as f:
        src = f.read()
    ns = {"__name__": "candidate_module"}
    code = compile(src, path, "exec")
    exec(code, ns)
    fn = ns.get("index_minimum")
    if not callable(fn):
        raise RuntimeError("index_minimum not defined by candidate source")
    return fn


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    cand_path = os.path.join(here, "block-0.txt")
    inputs_path = os.path.join(os.getcwd(), "inputs.json")

    try:
        fn = load_candidate(cand_path)
    except Exception as e:
        emit({"results": [], "harness_error": "candidate load failed: " + repr(e)})
        return

    try:
        with open(inputs_path, "r", encoding="utf-8") as f:
            cases = json.load(f)
        if not isinstance(cases, list):
            raise ValueError("inputs.json must contain a list")
    except Exception as e:
        emit({"results": [], "harness_error": "inputs load failed: " + repr(e)})
        return

    results = []
    for case in cases:
        case_id = case.get("id") if isinstance(case, dict) else None
        buf = io.StringIO()
        try:
            # Adapter step from the contract: convert each [name, score] pair to a tuple.
            test_list = case["input"]["test_list"]
            arg = [tuple(pair) for pair in test_list]
            with contextlib.redirect_stdout(buf):
                value = fn(arg)
            # Confirm the observed value can be represented as JSON.
            json.dumps(value)
            results.append({"id": case_id, "actual": value})
        except Exception as e:
            results.append({"id": case_id, "error": type(e).__name__ + ": " + str(e)})

    emit({"results": results})


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        emit({"results": [], "harness_error": "unexpected: " + repr(e)})

import json
import io
import copy
import contextlib
import sys


def emit(obj):
    # Print exactly one JSON object on the real stdout.
    sys.stdout.write(json.dumps(obj))
    sys.stdout.write('\n')
    sys.stdout.flush()


def load_candidate():
    # Read the verbatim candidate source saved as block-0.txt.
    with open('block-0.txt', 'r', encoding='utf-8') as f:
        src = f.read()
    ns = {'__name__': 'candidate_block'}
    code = compile(src, 'block-0.txt', 'exec')
    # Capture any incidental stdout produced at module load.
    with contextlib.redirect_stdout(io.StringIO()):
        exec(code, ns)
    fn = ns.get('index_minimum')
    if not callable(fn):
        raise RuntimeError('index_minimum not defined by block-0.txt')
    return fn


def main():
    # Infrastructure setup: read inputs and load the candidate.
    try:
        with open('inputs.json', 'r', encoding='utf-8') as f:
            cases = json.load(f)
        if not isinstance(cases, list):
            raise ValueError('inputs.json must contain a list')
        fn = load_candidate()
    except Exception as e:
        emit({'results': [], 'harness_error': 'setup failed: ' + type(e).__name__ + ': ' + str(e)})
        return

    results = []
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        # Adapter step: deep copy the input so each case is independent,
        # then convert each [name, score] pair into a tuple.
        try:
            payload = copy.deepcopy(case['input'])
            test_list = [tuple(pair) for pair in payload['test_list']]
        except Exception as e:
            results.append({'id': cid, 'error': 'adapter: ' + type(e).__name__ + ': ' + str(e)})
            continue
        # Run the real candidate, discarding its incidental stdout.
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                value = fn(test_list)
            json.dumps(value)
            results.append({'id': cid, 'actual': value})
        except Exception as e:
            results.append({'id': cid, 'error': type(e).__name__ + ': ' + str(e)})
    emit({'results': results})


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        emit({'results': [], 'harness_error': 'unexpected: ' + type(e).__name__ + ': ' + str(e)})
